"""Scheduler — 定时任务调度。

参考 agentd/core/scheduler.py。
- TaskScheduler：轻量定时任务（interval/daily），后台线程轮询检查
心跳上报已统一走 WS 通道（由 WSClient + ws_gateway 处理），
不再需要独立的 HTTP Heartbeat 组件。
均只用标准库，daemon 线程不阻塞 HTTP 主服务。
"""
import json
import logging
import threading
import time
from datetime import datetime

logger = logging.getLogger("agent.scheduler")


class TaskScheduler:
    """轻量定时任务调度器。

    任务类型：
    - interval: 每 N 秒执行一次
    - daily: 每天指定时刻执行一次
    """

    def __init__(self):
        self._tasks = {}
        self._stop = threading.Event()
        self._thread = None

    def register(self, name, func, kind='interval',
                 interval=3600, hour=3, minute=0):
        """注册任务。kind='interval' 用 interval 秒；kind='daily' 用 hour:minute。"""
        self._tasks[name] = {
            'func': func,
            'kind': kind,
            'interval': interval,
            'hour': hour,
            'minute': minute,
            'last_run': 0.0,
            'last_day': None,
        }
        logger.info('定时任务已注册: %s (%s)', name, kind)

    def _due(self, task, now):
        if task['kind'] == 'interval':
            return now - task['last_run'] >= task['interval']
        if task['kind'] == 'daily':
            dt = datetime.fromtimestamp(now)
            today = dt.strftime('%Y-%m-%d')
            if task['last_day'] == today:
                return False
            return (dt.hour, dt.minute) >= (task['hour'], task['minute'])
        return False

    def _loop(self):
        while not self._stop.wait(30):
            now = time.time()
            for name, task in list(self._tasks.items()):
                if not self._due(task, now):
                    continue
                try:
                    task['func']()
                    logger.info('定时任务执行成功: %s', name)
                except Exception as e:  # noqa: BLE001
                    logger.error('定时任务 %s 执行失败: %s', name, e)
                task['last_run'] = now
                if task['kind'] == 'daily':
                    task['last_day'] = datetime.fromtimestamp(now).strftime('%Y-%m-%d')

    def start(self):
        if self._thread and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(
            target=self._loop, name='scheduler', daemon=True)
        self._thread.start()
        logger.info('定时任务调度器已启动（%d 个任务）', len(self._tasks))

    def stop(self):
        self._stop.set()

    def list_tasks(self):
        return [{'name': n, 'kind': t['kind'], 'interval': t['interval'],
                 'last_run': t['last_run']} for n, t in self._tasks.items()]


def build_default_scheduler(config, memory, token_meter):
    """组装默认任务：memory_archive（每 6 小时）+ token_report（每日）。"""
    scheduler = TaskScheduler()
    scheduler.register(
        'memory_archive',
        lambda: memory.archive_old(config.get('archive_days', 7)),
        kind='interval', interval=6 * 3600)
    scheduler.register(
        'token_report',
        lambda: logger.info('Token 用量: %s', json.dumps(
            token_meter.status(), ensure_ascii=False)),
        kind='daily', hour=1, minute=0)
    return scheduler
